export { default as SankeyChart } from "./src/SankeyChart.vue";
export { default as SankeyChartPlot } from "./src/SankeyChartPlot.vue";
export { default as SankeyChartTooltip } from "./src/SankeyChartTooltip.vue";
export { useSankeyChart } from "./src/context";
export type { SankeyChartProps, SankeyActive } from "./src/context";
export type {
  SankeyNode,
  SankeyLink,
  PlacedNode as SankeyPlacedNode,
  PlacedLink as SankeyPlacedLink,
} from "./src/model";
export type SankeyChartPlotProps = InstanceType<
  (typeof import("./src/SankeyChartPlot.vue"))["default"]
>["$props"];
export type SankeyChartTooltipProps = InstanceType<
  (typeof import("./src/SankeyChartTooltip.vue"))["default"]
>["$props"];

import { computed, reactive, ref, useId } from "vue";
import { useMediaQuery, useReducedMotion } from "../../../lib/composables";
import { activeSelection, context, formatNumber, usePlotSize } from "../../shared";
import {
  cleanSankey,
  layoutSankey,
  SANKEY_COLORS,
  type SankeyNode,
  type SankeyLink,
  type PlacedNode,
  type PlacedLink,
} from "./model";
export interface SankeyChartProps {
  nodes: readonly SankeyNode[];
  links: readonly SankeyLink[];
  label?: string;
  formatValue?: (value: number) => string;
  colors?: readonly string[];
  nodeWidth?: number;
  nodePadding?: number;
  activeId?: string | null;
  defaultActiveId?: string | null;
  className?: string;
}
export type SankeyActive =
  { type: "node"; node: PlacedNode } | { type: "link"; link: PlacedLink };
export function createSankeyModel(
  props: SankeyChartProps,
  emit: (event: any, ...args: any[]) => void,
) {
  const plotRef = ref<HTMLElement | null>(null),
    size = usePlotSize(plotRef, { width: 640, height: 320 });
  const data = computed(() => cleanSankey(props.nodes, props.links));
  const layout = computed(() =>
    layoutSankey(data.value, {
      ...size.value,
      nodeWidth: props.nodeWidth ?? 12,
      nodePadding: props.nodePadding ?? 16,
      colors: props.colors ?? SANKEY_COLORS,
    }),
  );
  const activeId = activeSelection(
    () => props.activeId,
    props.defaultActiveId ?? null,
    computed(() => [
      ...layout.value.nodes.map((node) => node.id),
      ...layout.value.links.map((link) => link.id),
    ]),
    (id) => {
      emit("update:activeId", id);
      emit("activeChange", id);
    },
  );
  const active = computed<SankeyActive | null>(() => {
    const node = layout.value.nodes.find((node) => node.id === activeId.value);
    if (node) return { type: "node", node };
    const link = layout.value.links.find((link) => link.id === activeId.value);
    return link ? { type: "link", link } : null;
  });
  return reactive({
    nodes: computed(() => layout.value.nodes),
    links: computed(() => layout.value.links),
    columns: computed(() => layout.value.columns),
    step: computed(() => layout.value.step),
    size,
    plotRef,
    activeId,
    active,
    setActive(id: string | null) {
      activeId.value = id;
    },
    tooltipOpen: ref(false),
    tooltipId: useId(),
    gradientId: useId().replace(/[^\w-]/g, ""),
    label: computed(() => props.label ?? "Sankey chart"),
    formatValue: computed(() => props.formatValue ?? formatNumber),
    empty: computed(() =>
      data.value.links.length
        ? null
        : props.nodes.length
          ? "No flows to show"
          : "No sankey data",
    ),
    reduce: useReducedMotion(),
    canHover: useMediaQuery("(hover: hover)"),
  });
}
export const sankeyContext =
  context<ReturnType<typeof createSankeyModel>>("SankeyChart");
export const useSankeyChart = sankeyContext.use;
export function emphasis(active: SankeyActive | null) {
  function node(node: PlacedNode) {
    if (!active) return true;
    return active.type === "node"
      ? node.id === active.node.id
      : node.id === active.link.source.id || node.id === active.link.target.id;
  }
  function link(link: PlacedLink) {
    if (!active) return true;
    return active.type === "node"
      ? link.source.id === active.node.id || link.target.id === active.node.id
      : link.id === active.link.id;
  }
  return { node, link };
}

export interface SankeyNode {
  id: string;
  label: string;
  color?: string;
  description?: string;
}
export interface SankeyLink {
  id?: string;
  source: string;
  target: string;
  value: number;
}
export type PlacedNode = Required<
  Pick<SankeyNode, "id" | "label" | "color">
> & {
  description?: string;
  value: number;
  inValue: number;
  outValue: number;
  depth: number;
  x0: number;
  x1: number;
  y0: number;
  y1: number;
};
export type PlacedLink = {
  id: string;
  source: PlacedNode;
  target: PlacedNode;
  value: number;
  share: number;
  width: number;
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  path: string;
};
export type SankeyData = {
  nodes: SankeyNode[];
  links: SankeyLink[];
  dropped: { invalid: SankeyLink[]; cycle: SankeyLink[] };
};
export const SANKEY_COLORS = [
  "#1d4ed8",
  "#7c3aed",
  "#0f766e",
  "#b45309",
  "#be123c",
  "#475569",
] as const;
export const linkId = (link: SankeyLink) =>
  link.id ?? `${link.source}:${link.target}`;

function append<T>(map: Map<string, T[]>, id: string, value: T) {
  const list = map.get(id);
  if (list) list.push(value);
  else map.set(id, [value]);
}

export function cleanSankey(
  nodes: readonly SankeyNode[],
  links: readonly SankeyLink[],
): SankeyData {
  const identities = new Map<string, SankeyNode>();
  nodes.forEach((node) => {
    if (!identities.has(node.id)) identities.set(node.id, node);
  });
  const invalid: SankeyLink[] = [];
  const edges = new Map<string, SankeyLink>();
  for (const edge of links) {
    if (
      !identities.has(edge.source) ||
      !identities.has(edge.target) ||
      edge.source === edge.target ||
      !Number.isFinite(edge.value) ||
      edge.value <= 0
    ) {
      invalid.push(edge);
      continue;
    }
    const key = linkId(edge);
    const previous = edges.get(key);
    if (!previous) edges.set(key, { ...edge, id: key });
    else if (
      edge.id === undefined &&
      previous.source === edge.source &&
      previous.target === edge.target
    )
      previous.value += edge.value;
    else invalid.push(edge);
  }
  const outgoing = new Map<string, SankeyLink[]>();
  edges.forEach((edge) => append(outgoing, edge.source, edge));
  const entered = new Set<string>();
  const finished = new Set<string>();
  const backEdges = new Set<SankeyLink>();
  for (const root of identities.keys()) {
    if (entered.has(root)) continue;
    entered.add(root);
    const traversal: { id: string; next: number }[] = [{ id: root, next: 0 }];
    while (traversal.length) {
      const frame = traversal[traversal.length - 1];
      const edge = outgoing.get(frame.id)?.[frame.next++];
      if (!edge) {
        finished.add(frame.id);
        traversal.pop();
        continue;
      }
      if (!entered.has(edge.target)) {
        entered.add(edge.target);
        traversal.push({ id: edge.target, next: 0 });
      } else if (!finished.has(edge.target)) backEdges.add(edge);
    }
  }
  const kept: SankeyLink[] = [];
  const cycle: SankeyLink[] = [];
  edges.forEach((edge) => (backEdges.has(edge) ? cycle : kept).push(edge));
  return {
    nodes: [...identities.values()],
    links: kept,
    dropped: { invalid, cycle },
  };
}

type LayoutOptions = {
  width: number;
  height: number;
  nodeWidth: number;
  nodePadding: number;
  colors: readonly string[];
};
type Flow = {
  link: SankeyLink;
  source: PlacedNode;
  target: PlacedNode;
  from: number;
  to: number;
};

export function layoutSankey(data: SankeyData, options: LayoutOptions) {
  const { width, height, nodeWidth, nodePadding, colors } = options;
  const incoming = new Map<string, SankeyLink[]>();
  const outgoing = new Map<string, SankeyLink[]>();
  const received = new Map<string, number>();
  const sent = new Map<string, number>();
  for (const edge of data.links) {
    append(incoming, edge.target, edge);
    append(outgoing, edge.source, edge);
    received.set(edge.target, (received.get(edge.target) ?? 0) + edge.value);
    sent.set(edge.source, (sent.get(edge.source) ?? 0) + edge.value);
  }
  const remaining = new Map(
    data.nodes.map((node) => [node.id, incoming.get(node.id)?.length ?? 0]),
  );
  const depth = new Map<string, number>();
  const ready = data.nodes
    .filter((node) => !remaining.get(node.id))
    .map((node) => node.id);
  ready.forEach((id) => depth.set(id, 0));
  for (let index = 0; index < ready.length; index++) {
    const id = ready[index];
    for (const edge of outgoing.get(id) ?? []) {
      depth.set(
        edge.target,
        Math.max(depth.get(edge.target) ?? 0, (depth.get(id) ?? 0) + 1),
      );
      const count = (remaining.get(edge.target) ?? 0) - 1;
      remaining.set(edge.target, count);
      if (count === 0) ready.push(edge.target);
    }
  }
  const linked = data.nodes.filter(
    (node) => received.has(node.id) || sent.has(node.id),
  );
  if (!linked.length || width <= 0 || height <= 0)
    return {
      nodes: [] as PlacedNode[],
      links: [] as PlacedLink[],
      columns: 0,
      step: 0,
    };
  let terminal = 0;
  for (const node of linked)
    terminal = Math.max(terminal, depth.get(node.id) ?? 0);
  const columns = terminal + 1;
  const step = columns > 1 ? (width - nodeWidth) / (columns - 1) : 0;
  const sourceIndices = new Map(
    data.nodes.map((node, index) => [node.id, index]),
  );
  const placed = linked.map((node): PlacedNode => {
    const inValue = received.get(node.id) ?? 0;
    const outValue = sent.get(node.id) ?? 0;
    const column = sent.has(node.id) ? (depth.get(node.id) ?? 0) : terminal;
    return {
      id: node.id,
      label: node.label,
      description: node.description,
      color:
        node.color ?? colors[(sourceIndices.get(node.id) ?? 0) % colors.length],
      value: Math.max(inValue, outValue),
      inValue,
      outValue,
      depth: column,
      x0: column * step,
      x1: column * step + nodeWidth,
      y0: 0,
      y1: 0,
    };
  });
  const nodesById = new Map(placed.map((node) => [node.id, node]));
  const lanes: PlacedNode[][] = Array.from({ length: columns }, () => []);
  for (const node of placed) lanes[node.depth].push(node);
  let padding = nodePadding;
  for (const lane of lanes)
    if (lane.length > 1)
      padding = Math.min(padding, (height * 0.5) / (lane.length - 1));
  let unit = Infinity;
  for (const lane of lanes) {
    if (!lane.length) continue;
    const sum = lane.reduce((value, node) => value + node.value, 0);
    unit = Math.min(unit, (height - (lane.length - 1) * padding) / sum);
  }
  for (const lane of lanes) {
    let cursor = 0;
    for (const node of lane) {
      node.y0 = cursor;
      node.y1 = cursor + node.value * unit;
      cursor = node.y1 + padding;
    }
    const offset = (height - (cursor - padding)) / 2;
    for (const node of lane) {
      node.y0 += offset;
      node.y1 += offset;
    }
  }
  function constrain(lane: PlacedNode[]) {
    let boundary = 0;
    for (const node of lane) {
      const shift = boundary - node.y0;
      if (shift > 0) {
        node.y0 += shift;
        node.y1 += shift;
      }
      boundary = node.y1 + padding;
    }
    boundary = height;
    for (let index = lane.length - 1; index >= 0; index--) {
      const node = lane[index];
      const shift = node.y1 - boundary;
      if (shift > 0) {
        node.y0 -= shift;
        node.y1 -= shift;
      }
      boundary = node.y0 - padding;
    }
  }
  function settle(lane: PlacedNode[], alpha: number, fromIncoming: boolean) {
    for (const node of lane) {
      let weighted = 0;
      let weight = 0;
      for (const edge of (fromIncoming ? incoming : outgoing).get(node.id) ??
        []) {
        const other = nodesById.get(fromIncoming ? edge.source : edge.target);
        if (!other) continue;
        weighted += ((other.y0 + other.y1) / 2) * edge.value;
        weight += edge.value;
      }
      if (weight) {
        const distance = (weighted / weight - (node.y0 + node.y1) / 2) * alpha;
        node.y0 += distance;
        node.y1 += distance;
      }
    }
    constrain(lane);
  }
  for (let iteration = 0; iteration < 6; iteration++) {
    const alpha = 0.99 ** iteration;
    for (let column = 1; column < columns; column++)
      settle(lanes[column], alpha, true);
    for (let column = columns - 2; column >= 0; column--)
      settle(lanes[column], alpha, false);
  }
  const leaving = new Map<string, Flow[]>();
  const arriving = new Map<string, Flow[]>();
  const flows: Flow[] = data.links.map((link) => ({
    link,
    source: nodesById.get(link.source)!,
    target: nodesById.get(link.target)!,
    from: 0,
    to: 0,
  }));
  for (const flow of flows) {
    append(leaving, flow.source.id, flow);
    append(arriving, flow.target.id, flow);
  }
  for (const node of placed) {
    let start = node.y0;
    for (const flow of (leaving.get(node.id) ?? []).sort(
      (a, b) => a.target.y0 - b.target.y0,
    )) {
      flow.from = start;
      start += flow.link.value * unit;
    }
    start = node.y0;
    for (const flow of (arriving.get(node.id) ?? []).sort(
      (a, b) => a.source.y0 - b.source.y0,
    )) {
      flow.to = start;
      start += flow.link.value * unit;
    }
  }
  const links: PlacedLink[] = flows.map(
    ({ link, source, target, from, to }) => {
      const band = link.value * unit;
      const x0 = source.x1,
        x1 = target.x0;
      const y0 = from + band / 2,
        y1 = to + band / 2;
      const middle = (x0 + x1) / 2;
      return {
        id: linkId(link),
        source,
        target,
        value: link.value,
        share: source.value ? link.value / source.value : 0,
        width: band,
        x0,
        x1,
        y0,
        y1,
        path: `M ${x0} ${y0} C ${middle} ${y0} ${middle} ${y1} ${x1} ${y1}`,
      };
    },
  );
  return { nodes: lanes.flat(), links, columns, step };
}

import {
  computed,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  watch,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from "vue";

const numeric = new Intl.NumberFormat("en-US", { maximumFractionDigits: 2 });
const compact = new Intl.NumberFormat("en-US", {
  notation: "compact",
  maximumFractionDigits: 1,
});
export const formatNumber = (value: number) => numeric.format(value);
export const formatCompact = (value: number) => compact.format(value);

export function context<T>(name: string) {
  const key: InjectionKey<T> = Symbol(name);
  function use(): T {
    const provided = inject(key);
    if (provided === undefined || provided === null)
      throw new Error(`${name} parts must be rendered inside ${name}.`);
    return provided;
  }
  return { key, use };
}

export function selection<T>(
  get: () => T | undefined,
  initial: T,
  change: (value: T) => void,
) {
  const fallback = ref(initial) as Ref<T>;
  return computed<T>({
    get() {
      const supplied = get();
      return supplied === undefined ? fallback.value : supplied;
    },
    set(value) {
      if (get() === undefined) fallback.value = value;
      change(value);
    },
  });
}

export function activeSelection(
  get: () => string | null | undefined,
  initial: string | null,
  ids: ComputedRef<string[]>,
  change: (id: string | null) => void,
) {
  const requested = selection(get, initial, change);
  const available = computed(() => new Set(ids.value));
  watch(available, (current) => {
    const id = requested.value;
    if (get() === undefined && id !== null && !current.has(id))
      requested.value = null;
  });
  return computed<string | null>({
    get() {
      const id = requested.value;
      return id !== null && available.value.has(id) ? id : null;
    },
    set: (id) => {
      requested.value = id;
    },
  });
}

export function usePlotSize(
  element: Ref<HTMLElement | null>,
  initial: { width: number; height: number },
) {
  const size = ref({ ...initial });
  let observer: ResizeObserver | undefined;
  let stop: (() => void) | undefined;
  onMounted(() => {
    if (typeof ResizeObserver === "undefined") return;
    observer = new ResizeObserver((entries) => {
      const entry = entries.find((item) => item.target === element.value);
      const box = entry?.contentRect;
      if (
        box &&
        box.width > 0 &&
        box.height > 0 &&
        (box.width !== size.value.width || box.height !== size.value.height)
      )
        size.value = { width: box.width, height: box.height };
    });
    stop = watch(
      element,
      (current, previous) => {
        if (previous) observer?.unobserve(previous);
        if (current) observer?.observe(current);
      },
      { immediate: true },
    );
  });
  onBeforeUnmount(() => {
    stop?.();
    observer?.disconnect();
  });
  return size;
}

export function moveFocus(
  event: KeyboardEvent,
  index: number,
  count: number,
  columns = 1,
) {
  if (count <= 0) return;
  const stride = Math.max(1, columns);
  const rowStart = Math.floor(index / stride) * stride;
  const destinations: Record<string, number> = {
    ArrowRight: index + 1,
    ArrowLeft: index - 1,
    ArrowDown: index + stride,
    ArrowUp: index - stride,
    Home: event.ctrlKey ? 0 : rowStart,
    End: event.ctrlKey ? count - 1 : rowStart + stride - 1,
  };
  if (!(event.key in destinations)) return;
  event.preventDefault();
  const current = event.currentTarget;
  if (!(current instanceof HTMLElement)) return;
  const entries = current
    .closest("[data-chart-keyboard]")
    ?.querySelectorAll<HTMLElement>("[data-chart-item]");
  const destination = Math.max(0, Math.min(count - 1, destinations[event.key]));
  entries?.[destination]?.focus();
}

export function unwrapModel<T extends object>(model: ComputedRef<T>): T {
  const descriptors = Object.fromEntries(
    Object.keys(model.value).map((key) => [
      key,
      {
        enumerable: true,
        get: () => model.value[key as keyof T],
      },
    ]),
  );
  return Object.defineProperties({} as T, descriptors);
}

import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";
import { layerManager, type Layer } from "./layers";

export function useControllable<T>(props: Record<string, any>, key: string, emit: (...args: any[]) => void, fallback: T) {
  const local = ref<T>(fallback) as Ref<T>;
  const read = () => props[key] as T | undefined;
  return computed<T>({
    get() { const supplied = read(); return supplied === undefined ? local.value : supplied; },
    set(value) { if (read() === undefined) local.value = value; emit(`update:${key}`, value); },
  });
}

export function useMediaQuery(query: string) {
  const matches = ref(false);
  let disconnect: (() => void) | undefined;
  onMounted(() => {
    if (typeof window.matchMedia !== "function") return;
    const media = window.matchMedia(query);
    const update = () => { matches.value = media.matches; };
    update();
    media.addEventListener?.("change", update);
    disconnect = () => media.removeEventListener?.("change", update);
  });
  onBeforeUnmount(() => disconnect?.());
  return matches;
}
export function useReducedMotion() { return useMediaQuery("(prefers-reduced-motion: reduce)"); }

const lockedProperties = ["overflow", "position", "top", "left", "right", "width"] as const;
let scrollOwners = 0;
let unlockPage: (() => void) | undefined;
function acquirePage() {
  if (scrollOwners++ === 0) {
    const body = document.body.style;
    const saved = lockedProperties.map(name => ({ name, value: body.getPropertyValue(name), priority: body.getPropertyPriority(name) }));
    const x = window.scrollX, y = window.scrollY;
    body.setProperty("overflow", "hidden");
    body.setProperty("position", "fixed");
    body.setProperty("left", `${-x}px`);
    body.setProperty("top", `${-y}px`);
    body.setProperty("right", "0px");
    body.setProperty("width", "100%");
    unlockPage = () => {
      for (const entry of saved) {
        if (entry.value) body.setProperty(entry.name, entry.value, entry.priority);
        else body.removeProperty(entry.name);
      }
      const root = document.documentElement.style;
      const behavior = root.getPropertyValue("scroll-behavior");
      const priority = root.getPropertyPriority("scroll-behavior");
      root.setProperty("scroll-behavior", "auto");
      window.scrollTo(x, y);
      if (behavior) root.setProperty("scroll-behavior", behavior, priority);
      else root.removeProperty("scroll-behavior");
    };
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--scrollOwners === 0) { unlockPage?.(); unlockPage = undefined; }
  };
}
export function useScrollLock(locked: Ref<boolean>) {
  let mounted = false;
  let release: (() => void) | undefined;
  const update = (value: boolean) => {
    if (!mounted) return;
    if (value && !release) release = acquirePage();
    if (!value && release) { release(); release = undefined; }
  };
  onMounted(() => { mounted = true; update(locked.value); });
  watch(locked, update);
  onBeforeUnmount(() => { release?.(); release = undefined; mounted = false; });
}

export function resolveElement<T extends Element = HTMLElement>(value: unknown): T | null {
  if (!value) return null;
  const unwrapped = (value as { $el?: unknown }).$el ?? value;
  return typeof (unwrapped as Element).nodeType === "number" && (unwrapped as Element).nodeType === 1 ? unwrapped as T : null;
}
const focusable = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function createLayer(modal: boolean, panel?: { readonly value: unknown }): Layer {
  return { key: Symbol("orvui-layer"), modal, owner: getCurrentInstance(), surface: () => resolveElement(panel?.value), returnTo: null };
}
export function useOverlay(open: Ref<boolean>, panel: Ref<HTMLElement | null>, close: () => void, initialFocus?: () => HTMLElement | undefined) {
  const layer = createLayer(true, panel);
  let mounted = false;
  let revision = 0;
  const sync = async (value: boolean) => {
    const current = ++revision;
    if (!mounted) return;
    if (!value) { layerManager.detach(layer, true); return; }
    if (!layerManager.attach(layer)) return;
    await nextTick();
    if (!mounted || current !== revision || !open.value || !layerManager.top(layer)) return;
    (initialFocus?.() ?? layer.surface()?.querySelector<HTMLElement>(focusable) ?? layer.surface())?.focus({ preventScroll: true });
  };
  const onKey = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !open.value) return;
    if (event.key === "Escape" && layerManager.top(layer)) {
      event.preventDefault(); event.stopPropagation(); close(); return;
    }
    if (event.key !== "Tab" || !layerManager.modal(layer)) return;
    const candidates = new Set<HTMLElement>();
    for (const surface of layerManager.scopes(layer)) {
      for (const node of surface.querySelectorAll<HTMLElement>(focusable)) {
        if (node.getClientRects().length > 0 && !node.closest("[inert]")) candidates.add(node);
      }
    }
    event.preventDefault();
    const nodes = [...candidates];
    if (!nodes.length) { layer.surface()?.focus(); return; }
